                            translationHtml: "<span class='t-S'>それは</span> <span class='t-V'>かつて考えられていた</span> <span class='t-O'>[医薬品の使用は人間特有の特性であると]</span>、しかし <span class='t-M'>(過去50年ほどの間に)</span>、<span class='t-S'>科学者たちは</span> <span class='t-V'>報告してきた</span> <span class='t-O'>動物が自己治療のために天然の治療薬を使用する多くの事例を</span>。",
