                id: 25,
                text: "According to the first paragraph, Étienne Léopold Trouvelot",
                translation: "第1段落によると、エティエンヌ・レオポルド・トゥルーヴロは",
                choices: [
                    { id: 1, text: "hoped to grow the silk industry in Europe by taking moths there that he collected in the United States.", translation: "アメリカで集めた蛾をヨーロッパに持っていくことで、ヨーロッパの絹産業を成長させたいと望んでいた。", isCorrect: false },
                    { id: 2, text: "bred a new variety of moth that helped to save the silk industry by increasing the amount of silk that could be produced.", translation: "生産できる絹の量を増やすことで絹産業を救うのに役立つ新しい品種の蛾を育てた。", isCorrect: false },
                    { id: 3, text: "accidentally introduced a species of moth to the United States that caused widespread environmental damage.", translation: "誤ってアメリカに蛾の一種を持ち込み、広範な環境被害を引き起こした。", isCorrect: true, highlight: "accidentally introduced ... environmental damage" },
                    { id: 4, text: "found a way to protect spongy moths from a fatal disease that had greatly reduced their numbers in Europe.", translation: "ヨーロッパで数を大きく減らした致命的な病気からスポンジモスを守る方法を見つけた。", isCorrect: false }
                ],
                hint: { paragraphId: 1, description: "第1段落でスポンジモスが逃げ出した結果を確認。", targetSentenceId: 9, highlightWord: "stripping many trees of their leaves", highlightWordSentenceId: 9 },
