                    { id: 2, text: "Trouvelot never became well-known during his lifetime because most people had little interest in astronomy.", translation: "ほとんどの人が天文学にほとんど興味を持っていなかったため、トゥルーヴロは生涯を通じて有名にならなかった。", isCorrect: false },
                    { id: 3, text: "The scientific value of Trouvelot's drawings prevents them from being put on public display for people to enjoy.", translation: "トゥルーヴロのスケッチの科学的価値が、人々が楽しめるよう公開展示されることを妨げている。", isCorrect: false },
                    { id: 4, text: "The technology that proved the high quality of Trouvelot's illustrations was also responsible for them becoming unnecessary.", translation: "トゥルーヴロのイラストの高品質を証明した技術が、それらを不要にする原因でもあった。", isCorrect: true, highlight: "technology ... proved ... unnecessary" }
