                    { id: 4, text: "the United States took action to assist European countries partly because doing so would also benefit the United States.", translation: "アメリカがヨーロッパ諸国を支援する行動を起こしたのは、そうすることがアメリカにも利益をもたらすからでもあった。", isCorrect: true, highlight: "assist European countries ... benefit the United States" }
