                choiceAdvice: "体制の結論。1: IMFが金連動を主張していれば(more successful?), 2: 失敗したが組織が残る(ended in failure, owe existence), 3: もっと早く終わらせるべき(should have ended earlier?), 4: IMFと世界銀行が崩壊の原因(main reason?)。",
                logic: [{ type: "text", content: "本文: \"In 1971, the United States suspended the dollar's convertibility to gold, effectively ending the Bretton Woods system\"" }, { type: "text", content: "続き: \"Nevertheless, its legacy lives on in the shape of the International Monetary Fund (IMF) and the World Bank, which emerged out of the system\"" }, { type: "text", content: "【ポイント】体制は終わった（失敗）が、IMFと世界銀行という遺産が現代に生き続けている。" }, { type: "arrow", content: "↓" }, { type: "text", content: "選択肢2: \"Although the system itself ended in failure, some economic organizations ... owe their existence to it\"" }, { type: "conclusion", content: "正解: 2" }]
