                        id: 17,
                        text: "A further obstacle to scientific and technological innovation often cited by economists is the fact that populations are aging.",
                        translation: "経済学者によってしばしば引用される科学的および技術的革新に対するさらなる障害は、人口が高齢化しているという事実です。",
